public class CircularQueue<T>{private final T[]data;private int head,size;public CircularQueue(T[]storage){data=storage;}public void put(T value){if(size==data.length){System.out.println("full");return;}data[(head+size++)%data.length]=value;}public Object get(){if(size==0){System.out.println("empty");return null;}T value=data[head];head=(head+1)%data.length;size--;return value;}}
